				"workouts",
				"routines",
				"templates",
				"measurements",
				"folders",
				"profile",
				"workflows",
			]).toContain(definition.feature);
			expect(["read", "write"]).toContain(definition.kind);
			expect([
				"list",
				"get",
				"search",
				"create",
				"update",
				"count",
				"sync",
			]).toContain(definition.operation);
		}
	});

	it("advertises output schemas for read tools", async () => {
		const { tools } = await client.listTools();
		const summary = tools.find(({ name }) => name === "get-training-summary");

		expect(summary?.outputSchema).toBeDefined();
	});
	it("exposes only snake_case public input property names", async () => {
		const { tools } = await client.listTools();
		const propertyNames: string[] = [];
		const visit = (schema: SchemaObject): void => {
			if (schema.properties) {
				for (const [name, child] of Object.entries(schema.properties)) {
					propertyNames.push(name);
					visit(child);
				}
			}
			if (schema.items) visit(schema.items);
			if (schema.anyOf) {
				for (const branch of schema.anyOf) visit(branch);
			}
		};
		for (const tool of tools) {
			visit(schemaObjectSchema.parse(tool.inputSchema));
		}
		expect(
			propertyNames.filter((name) => !/^[a-z][a-z0-9_]*$/u.test(name)),
		).toEqual([]);
	});
});

import type { McpServer } from "@modelcontextprotocol/server";
import { McpServer as Server } from "@modelcontextprotocol/server";
import { createHevyClient, type HevyClient } from "@hevy-mcp/hevy-client";
import type {
	GetV1RoutinesQuery,
	GetV1WorkoutsQuery,
} from "@hevy-mcp/hevy-client/types";
import { vi } from "vitest";

export function createMockHevyClient() {
	const methods = {
		getWorkouts: vi.fn(),
		getWorkout: vi.fn(),
		createWorkout: vi.fn(),
		updateWorkout: vi.fn(),
		getWorkoutCount: vi.fn(),
		getWorkoutEvents: vi.fn(),
		getRoutines: vi.fn(),
		getRoutineById: vi.fn(),
		createRoutine: vi.fn(),
		updateRoutine: vi.fn(),
		getExerciseTemplates: vi.fn(),
		getExerciseTemplate: vi.fn(),
		getExerciseHistory: vi.fn(),
		createExerciseTemplate: vi.fn(),
		getRoutineFolders: vi.fn(),
		createRoutineFolder: vi.fn(),
		getRoutineFolder: vi.fn(),
		getBodyMeasurements: vi.fn(),
		getBodyMeasurement: vi.fn(),
		createBodyMeasurement: vi.fn(),
		updateBodyMeasurement: vi.fn(),
		getUserInfo: vi.fn(),
	} satisfies HevyClient;

	const client = createHevyClient({
		apiKey: "test-key",
		maxGetRetries: 0,
		fetch: async (input, init) => {
			const url = input instanceof Request ? input.url : String(input);
			const parsedUrl = new URL(url);
			const request = input instanceof Request ? input : new Request(url, init);
			const method = request.method.toUpperCase();
			const bodyText =
				method === "GET" || method === "HEAD"
					? undefined
					: await request.text();
			const body =
				bodyText === undefined || bodyText.length === 0
					? undefined
					: JSON.parse(bodyText);
			const jsonResponse = <T>(data: T | undefined) =>
				new Response(JSON.stringify(data ?? {}), {
					status: 200,
					headers: { "content-type": "application/json" },
				});
			const query =
				parsedUrl.search.length === 0
					? undefined
					: {
							page: Number(parsedUrl.searchParams.get("page")),
							pageSize: Number(parsedUrl.searchParams.get("pageSize")),
							since: parsedUrl.searchParams.get("since") ?? undefined,
						};
			switch (parsedUrl.pathname) {
				case "/v1/workouts": {
					if (method === "POST") {
						return jsonResponse(await methods.createWorkout(body));
					}
					if (method === "GET") {
						const params =
							query === undefined
								? undefined
								: ({
										page: query.page,
										pageSize: query.pageSize,
									} satisfies GetV1WorkoutsQuery);
						return jsonResponse(
							params === undefined
								? await methods.getWorkouts()
								: await methods.getWorkouts(params),
						);
					}
					break;
				}
				case "/v1/workouts/events": {
					return jsonResponse(
						await methods.getWorkoutEvents({
							page: query?.page,
							pageSize: query?.pageSize,
							since: query?.since,
						}),
					);
				}
				case "/v1/workouts/count": {
					return jsonResponse(await methods.getWorkoutCount());
				}
				case "/v1/routines": {
					if (method === "POST") {
						return jsonResponse(await methods.createRoutine(body));
					}
					if (method === "GET") {
						const params =
							query === undefined
								? undefined
								: ({
										page: query.page,
										pageSize: query.pageSize,
									} satisfies GetV1RoutinesQuery);
						return jsonResponse(
							params === undefined
								? await methods.getRoutines()
								: await methods.getRoutines(params),
						);
					}
					break;
				}
			}
			if (parsedUrl.pathname.startsWith("/v1/workouts/")) {
				const workoutId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/workouts/".length),
				);
				if (method === "PUT") {
					return jsonResponse(await methods.updateWorkout(workoutId, body));
				}
				return jsonResponse(await methods.getWorkout(workoutId));
			}
			if (parsedUrl.pathname.startsWith("/v1/routines/")) {
				const routineId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/routines/".length),
				);
				if (method === "PUT") {
					return jsonResponse(await methods.updateRoutine(routineId, body));
				}
				return jsonResponse(await methods.getRoutineById(routineId));
			}
			if (parsedUrl.pathname === "/v1/exercise_templates") {
				if (method === "POST") {
					return jsonResponse(await methods.createExerciseTemplate(body));
				}
				return jsonResponse(
					await methods.getExerciseTemplates({
						page: query?.page,
						pageSize: query?.pageSize,
					}),
				);
			}
			if (parsedUrl.pathname.startsWith("/v1/exercise_templates/")) {
				const exerciseTemplateId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/exercise_templates/".length),
				);
				return jsonResponse(
					await methods.getExerciseTemplate(exerciseTemplateId),
				);
			}
			if (parsedUrl.pathname.startsWith("/v1/exercise_history/")) {
				const exerciseTemplateId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/exercise_history/".length),
				);
				const historyQuery: Partial<Record<"start_date" | "end_date", string>> =
					{};
				const startDate = parsedUrl.searchParams.get("start_date");
				const endDate = parsedUrl.searchParams.get("end_date");
				if (startDate !== null) historyQuery.start_date = startDate;
				if (endDate !== null) historyQuery.end_date = endDate;
				return jsonResponse(
					await methods.getExerciseHistory(exerciseTemplateId, historyQuery),
				);
			}
			if (parsedUrl.pathname === "/v1/routine_folders") {
				if (method === "POST") {
					return jsonResponse(await methods.createRoutineFolder(body));
				}
				return jsonResponse(
					await methods.getRoutineFolders({
						page: query?.page,
						pageSize: query?.pageSize,
					}),
				);
			}
			if (parsedUrl.pathname.startsWith("/v1/routine_folders/")) {
				const folderId = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/routine_folders/".length),
				);
				return jsonResponse(await methods.getRoutineFolder(folderId));
			}
			if (parsedUrl.pathname === "/v1/body_measurements") {
				if (method === "POST") {
					return jsonResponse(await methods.createBodyMeasurement(body));
				}
				return jsonResponse(
					await methods.getBodyMeasurements({
						page: query?.page,
						pageSize: query?.pageSize,
					}),
				);
			}
			if (parsedUrl.pathname.startsWith("/v1/body_measurements/")) {
				const date = decodeURIComponent(
					parsedUrl.pathname.slice("/v1/body_measurements/".length),
				);
				if (method === "PUT") {
					return jsonResponse(await methods.updateBodyMeasurement(date, body));
				}
				return jsonResponse(await methods.getBodyMeasurement(date));
			}
			if (parsedUrl.pathname === "/v1/user/info") {
				return jsonResponse(await methods.getUserInfo());
			}
			return new Response("{}", { status: 404 });
		},
	});
	Object.assign(client, methods);
	return client as HevyClient & typeof methods;
}

export function createMockMcpServer() {
	const server = new Server({ name: "test-server", version: "0.0.0" });
	const registerTool = vi.spyOn(server, "registerTool");
	const registerResource = vi.spyOn(server, "registerResource");
	return { server, registerResource, registerTool } satisfies {
		server: McpServer;
		registerResource: typeof registerResource;
		registerTool: typeof registerTool;
	};
}

import { Effect } from "effect";

type EffectOperation<TArgs extends readonly unknown[], TResult> = {
	readonly effect: (...args: TArgs) => Effect.Effect<TResult, unknown, never>;
};

export function requireOperation<T>(operation: T | undefined, id: string): T {
	if (operation === undefined) {
		throw new Error(`Operation ${id} is unavailable.`);
	}
	return operation;
}

export function operationEffect<TArgs extends readonly unknown[], TResult>(
	operation: EffectOperation<TArgs, TResult>,
	...args: TArgs
): Effect.Effect<TResult, unknown, never> {
	return Effect.suspend(() => operation.effect(...args));
}

/**
 * Projections from Hevy API types to the sparse snake_case MCP contract.
 * Pure functions over their input; schemas they fill live in output-schemas.ts.
 */
import type {
	BodyMeasurement,
	ExerciseHistoryEntry,
	Routine,
	RoutineFolder,
	Workout,
} from "@hevy-mcp/hevy-client/types";
import type {
	CompactRoutine,
	FormattedBodyMeasurement,
	FormattedExerciseHistoryEntry,
	FormattedRoutine,
	FormattedRoutineExercise,
	FormattedRoutineFolder,
	FormattedRoutineSet,
	FormattedWorkout,
	FormattedWorkoutExercise,
	FormattedWorkoutSet,
	FormattedWorkoutSummary,
} from "./output-schemas.js";
import { createSafeErrorDiagnostic } from "./error-policy.js";

type ExerciseWithSupersetVariants = {
	supersets_id?: number | null;
	superset_id?: number | null;
};

function getSupersetId(exercise: ExerciseWithSupersetVariants): number | null {
	if (exercise.superset_id !== undefined) {
		return exercise.superset_id;
	}

	if (exercise.supersets_id !== undefined) {
		return exercise.supersets_id;
	}

	return null;
}

/**
 * Project a workout into the sparse snake_case MCP contract.
 */
export function projectWorkout(workout: Workout): FormattedWorkout {
	const result: FormattedWorkout = {
		duration: calculateDuration(workout.start_time, workout.end_time),
	};
	if (workout.id != null) result.id = workout.id;
	if (workout.routine_id != null) result.routine_id = workout.routine_id;
	if (workout.title != null) result.title = workout.title;
	if (workout.description != null) result.description = workout.description;
	if (workout.start_time != null) result.start_time = workout.start_time;
	if (workout.end_time != null) result.end_time = workout.end_time;
	if (workout.created_at != null) result.created_at = workout.created_at;
	if (workout.updated_at != null) result.updated_at = workout.updated_at;
	if (workout.exercises) {
		result.exercises = workout.exercises.map((exercise) => {
			const projected: FormattedWorkoutExercise = {};
			if (exercise.index !== undefined) projected.index = exercise.index;
			if (exercise.title != null) projected.title = exercise.title;
			if (exercise.exercise_template_id != null)
				projected.exercise_template_id = exercise.exercise_template_id;
			if (exercise.notes != null) projected.notes = exercise.notes;
			const supersetId = getSupersetId(exercise);
			if (supersetId != null) projected.supersets_id = supersetId;
			if (exercise.sets)
				projected.sets = exercise.sets.map((set) => {
					const projectedSet: FormattedWorkoutSet = {};
					if (set.index !== undefined) projectedSet.index = set.index;
					if (set.type != null) projectedSet.type = set.type;
					if (set.weight_kg != null) projectedSet.weight_kg = set.weight_kg;
					if (set.reps != null) projectedSet.reps = set.reps;
					if (set.distance_meters != null)
						projectedSet.distance_meters = set.distance_meters;
					if (set.duration_seconds != null)
						projectedSet.duration_seconds = set.duration_seconds;
					if (set.rpe != null) projectedSet.rpe = set.rpe;
					if (set.custom_metric != null)
						projectedSet.custom_metric = set.custom_metric;
					return projectedSet;
				});
			return projected;
		});
	}
	return result;
}

export function summarizeWorkout(workout: Workout): FormattedWorkoutSummary {
	const exercises = workout.exercises ?? [];
	const result: FormattedWorkoutSummary = {
		duration: calculateDuration(workout.start_time, workout.end_time),
		exercise_count: exercises.length,
		set_count: exercises.reduce(
			(total, exercise) => total + (exercise.sets?.length ?? 0),
			0,
		),
	};
	if (workout.id != null) result.id = workout.id;
	if (workout.title != null) result.title = workout.title;
	if (workout.start_time != null) result.start_time = workout.start_time;
	if (workout.end_time != null) result.end_time = workout.end_time;
	return result;
}

export function projectRoutine(routine: Routine): FormattedRoutine {
	const result: FormattedRoutine = {};
	if (routine.id != null) result.id = routine.id;
	if (routine.title != null) result.title = routine.title;
	if (routine.folder_id != null) result.folder_id = routine.folder_id;
	if (routine.created_at != null) result.created_at = routine.created_at;
	if (routine.updated_at != null) result.updated_at = routine.updated_at;
	if (routine.exercises)
		result.exercises = routine.exercises.map((exercise) => {
			const projected: FormattedRoutineExercise = {};
			if (exercise.title != null) projected.title = exercise.title;
			if (exercise.index !== undefined) projected.index = exercise.index;
			if (exercise.exercise_template_id != null)
				projected.exercise_template_id = exercise.exercise_template_id;
			if (exercise.notes != null) projected.notes = exercise.notes;
			const supersetId = getSupersetId(exercise);
			if (supersetId != null) projected.supersets_id = supersetId;
			if (exercise.rest_seconds != null)
				projected.rest_seconds = exercise.rest_seconds;
			if (exercise.sets)
				projected.sets = exercise.sets.map((set) => {
					const projectedSet: FormattedRoutineSet = {};
					if (set.index !== undefined) projectedSet.index = set.index;
					if (set.type != null) projectedSet.type = set.type;
					if (set.weight_kg != null) projectedSet.weight_kg = set.weight_kg;
					if (set.reps != null) projectedSet.reps = set.reps;
					if (set.distance_meters != null)
						projectedSet.distance_meters = set.distance_meters;
					if (set.duration_seconds != null)
						projectedSet.duration_seconds = set.duration_seconds;
					if (set.rpe != null) projectedSet.rpe = set.rpe;
					if (set.custom_metric != null)
						projectedSet.custom_metric = set.custom_metric;
					if (
						set.rep_range &&
						(set.rep_range.start != null || set.rep_range.end != null)
					) {
						const repRange: NonNullable<FormattedRoutineSet["rep_range"]> = {};
						if (set.rep_range.start != null)
							repRange.start = set.rep_range.start;
						if (set.rep_range.end != null) repRange.end = set.rep_range.end;
						projectedSet.rep_range = repRange;
					}
					return projectedSet;
				});
			return projected;
		});
	return result;
}

export function summarizeRoutine(routine: Routine): CompactRoutine {
	const exercises = routine.exercises ?? [];
	const result: CompactRoutine = {
		exercise_count: exercises.length,
		set_count: exercises.reduce(
			(total, exercise) => total + (exercise.sets?.length ?? 0),
			0,
		),
	};
	if (routine.id != null) result.id = routine.id;
	if (routine.title != null) result.title = routine.title;
	if (routine.folder_id != null) result.folder_id = routine.folder_id;
	if (routine.updated_at != null) result.updated_at = routine.updated_at;
	return result;
}

export function projectRoutineFolder(
	folder: RoutineFolder,
): FormattedRoutineFolder {
	return {
		id: folder.id,
		title: folder.title,
		created_at: folder.created_at,
		updated_at: folder.updated_at,
	};
}

export function calculateDuration(
	startTime: string | number | null | undefined,
	endTime: string | number | null | undefined,
): string {
	if (!startTime || !endTime) return "Unknown duration";

	try {
		const start = new Date(startTime);
		const end = new Date(endTime);
		if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
			return "Unknown duration";
		}
		const durationMs = end.getTime() - start.getTime();
		if (durationMs < 0) {
			return "Invalid duration (end time before start time)";
		}
		const hours = Math.floor(durationMs / (1000 * 60 * 60));
		const minutes = Math.floor((durationMs % (1000 * 60 * 60)) / (1000 * 60));
		const seconds = Math.floor((durationMs % (1000 * 60)) / 1000);
		return `${hours}h ${minutes}m ${seconds}s`;
	} catch (error) {
		console.error(
			"Error calculating duration",
			createSafeErrorDiagnostic(error),
		);
		return "Unknown duration";
	}
}

export function normalizeExerciseHistoryEntry(
	entry: ExerciseHistoryEntry,
): FormattedExerciseHistoryEntry {
	const result: FormattedExerciseHistoryEntry = {};
