import type { UserInfo } from "@hevy-mcp/hevy-client/types";
import type { ToolDefinition } from "./define-tool.js";
import type { ToolRuntime } from "./tool-runtime.js";
import { userResponse } from "../utils/response-contracts.js";
import { readOnlyAnnotations } from "../utils/tool-annotations.js";
import { HevyOperationsService } from "../effect-services.js";
import { operationEffect, requireOperation } from "./operation-helpers.js";

const getUserInfoSchema = {} as const;

const getUserInfoDefinition: ToolDefinition<
	typeof getUserInfoSchema,
	UserInfo | undefined
> = {
	name: "get-user-info",
	feature: "profile",
	operation: "get",
	description:
		"Read-only. Returns the authenticated Hevy user ID, display name, and public profile URL.",
	inputSchema: getUserInfoSchema,
	kind: "read",
	outputSchema: userResponse.outputSchema,
	annotations: readOnlyAnnotations("Get User Info"),
	responseContract: userResponse,
	execute: (runtime: ToolRuntime) =>
		operationEffect(
			requireOperation(
				runtime.service(HevyOperationsService).user?.get,
				"user.get",
			),
			runtime.execution,
		),
};

export const userToolDefinitions = [getUserInfoDefinition] as const;

import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
import type { ToolRuntime } from "./tool-runtime.js";

export const hevyToolDefinitions = [
	...workoutToolDefinitions,
	...routineToolDefinitions,
	...templateToolDefinitions,
	...folderToolDefinitions,
	...bodyMeasurementToolDefinitions,
	...workflowToolDefinitions,
	...routineDiscoveryToolDefinitions,
] as const;

/**
 * Move the one-time tool schema conversion into module scope.
 *
 * Tool schemas are module-level constants, and their compact JSON Schema is
 * memoized per definition by `getRegisteredToolConfig`. Populating the memo is
 * not enough: `compactJsonSchema` stores the actual `z.toJSONSchema` work
 * behind lazy `input`/`output` closures, and the MCP SDK invokes those during
 * `registerTool`. This forces the exact conversions the SDK consumes (`input`
 * for each `inputSchema`, `output` for each read tool `outputSchema`) so a
 * first request only reads already-converted schemas.
 *
 * On isolate-based edge runtimes (Cloudflare Workers) module-scope work runs
 * during isolate warm-up, outside a request's billed CPU, so calling this at
 * module scope keeps the first request of a fresh isolate fast. Idempotent,
 * and a no-op after every conversion has been computed once.
 */
export function preloadHevyToolSchemas(): void {
	for (const definition of hevyToolDefinitions) {
		const config = getRegisteredToolConfig(definition);
		preloadCompactJsonSchema(config.inputSchema, "input");
		if (config.outputSchema) {
			preloadCompactJsonSchema(config.outputSchema, "output");
		}
	}
}

/** Register every Hevy tool in its production ordering. */
export function registerHevyTools(
	server: ToolRegistrar,
	runtime: ToolRuntime,
): void {
	for (const definition of hevyToolDefinitions) {
		registerToolDefinition(server, runtime, definition);
	}
}

import { Cache, Effect } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it, vi } from "vitest";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import {
	createExerciseTemplateCatalog,
	type ExerciseTemplateCatalog,
	type ExerciseTemplateCatalogCache,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./exercise-template-catalog.js";

type ListAll = Pick<TemplatesListAllOperation, "effect">;
type ListAllError = Effect.Error<ReturnType<ListAll["effect"]>>;

function createCatalog(
	listAll: ListAll,
	cache?: ExerciseTemplateCatalogCache,
): ExerciseTemplateCatalog {
	const serverCache =
		cache ??
		Effect.runSync(
			Cache.make({
				capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
				timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
				lookup: (_key: string) => listAll.effect(),
			}),
		);
	return createExerciseTemplateCatalog({ templates: { listAll } }, serverCache);
}

function operation(effect: ListAll["effect"]): ListAll {
	return { effect };
}

describe("exercise template catalog", () => {
	it("reset clears the server cache and forces a fresh catalog request", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.succeed([{ id: "first" }]))
			.mockReturnValueOnce(Effect.succeed([{ id: "second" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		catalog.reset();
		await expect(catalog.get()).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("deduplicates concurrent cache misses", async () => {
		let resolveLookup: ((templates: ExerciseTemplate[]) => void) | undefined;
		const listAll = vi.fn<ListAll["effect"]>().mockImplementation(() =>
			Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
				resolveLookup = (templates) => resume(Effect.succeed(templates));
			}),
		);
		const catalog = createCatalog(operation(listAll));

		const first = Effect.runPromise(catalog.effect());
		const second = Effect.runPromise(catalog.effect());
		await Promise.resolve();
		expect(listAll).toHaveBeenCalledOnce();

		resolveLookup?.([{ id: "shared", title: "Shared" }]);
		await expect(Promise.all([first, second])).resolves.toEqual([
			[{ id: "shared", title: "Shared" }],
			[{ id: "shared", title: "Shared" }],
		]);
	});

	it("does not share controlled calls between independently cancellable callers", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					const signal = options?.signal;
					if (signal?.aborted) {
						resume(Effect.fail(signal.reason));
						return;
					}
					const onAbort = () =>
						resume(Effect.fail(signal?.reason ?? new Error("aborted")));
					signal?.addEventListener("abort", onAbort, { once: true });
					const template =
						signal === firstController.signal ? "first" : "second";
					const timer = setTimeout(
						() => resume(Effect.succeed([{ id: template }])),
						template === "first" ? 100 : 20,
					);
					return Effect.sync(() => {
						clearTimeout(timer);
						signal?.removeEventListener("abort", onAbort);
					});
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		firstController.abort(new DOMException("first canceled", "AbortError"));

		await expect(first).rejects.toMatchObject({ name: "AbortError" });
		await expect(second).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("uses templates.listAll rather than a Promise client for lookup", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValue(
				Effect.succeed([{ id: "template-1", title: "Template 1" }]),
			);
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toEqual([
			{ id: "template-1", title: "Template 1" },
		]);
		expect(listAll).toHaveBeenCalledOnce();
	});

	it("reloads after the five-minute TTL", async () => {
		let calls = 0;
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation(() =>
				Effect.succeed([{ id: `template-${++calls}` }]),
			);
		const catalog = createCatalog(operation(listAll));
		const program = Effect.gen(function* () {
			const first = yield* catalog.effect();
			yield* TestClock.adjust(
				`${EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS} millis`,
			);
			const second = yield* catalog.effect();
			return [first, second] as const;
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toEqual([[{ id: "template-1" }], [{ id: "template-2" }]]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("invalidates a failed lookup before the next call", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.fail(new Error("temporary failure")))
			.mockReturnValueOnce(Effect.succeed([{ id: "recovered" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).rejects.toThrow("temporary failure");
		await expect(catalog.get()).resolves.toMatchObject([{ id: "recovered" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("does not let an older controlled load replace a newer result", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const pending: Array<{
			signal: AbortSignal | undefined;
			resume: (effect: Effect.Effect<ExerciseTemplate[]>) => void;
		}> = [];
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					pending.push({ resume, signal: options?.signal });
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		await vi.waitFor(() => expect(pending).toHaveLength(2));

		pending[1]?.resume(Effect.succeed([{ id: "newer" }]));
		await expect(second).resolves.toMatchObject([{ id: "newer" }]);
		pending[0]?.resume(Effect.succeed([{ id: "older" }]));
		await expect(first).resolves.toMatchObject([{ id: "older" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "newer" }]);
		expect(pending.map(({ signal }) => signal)).toEqual([
			firstController.signal,
			secondController.signal,
		]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});
});

import { Cache, Effect, Fiber } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it } from "vitest";

const makeCache = <Value, Error = never>(
	lookup: (key: string) => Effect.Effect<Value, Error>,
	options: {
		readonly capacity?: number;
		readonly timeToLive?: Parameters<typeof Cache.make>[0]["timeToLive"];
	} = {},
) =>
	Cache.make<string, Value, Error>({
		capacity: options.capacity ?? 2,
		lookup,
		timeToLive: options.timeToLive ?? "1 minute",
	});

describe("exercise template cache", () => {
	it("returns cached values for subsequent hits before TTL expiry", async () => {
		let lookups = 0;
		const program = Effect.gen(function* () {
			const cache = yield* makeCache(() =>
				Effect.sync(() => {
					lookups += 1;
					return "bench";
				}),
			);
			const first = yield* Cache.get(cache, "catalog");
			const second = yield* Cache.get(cache, "catalog");
			return [first, second] as const;
		});

		await expect(Effect.runPromise(program)).resolves.toEqual([
			"bench",
			"bench",
		]);
		expect(lookups).toBe(1);
	});

	it("expires entries under the Effect test clock", async () => {
		let lookups = 0;
		const program = Effect.gen(function* () {
			const cache = yield* makeCache(
				() =>
					Effect.sync(() => {
						lookups += 1;
						return lookups;
					}),
				{ timeToLive: "1 second" },
			);
			const first = yield* Cache.get(cache, "catalog");
			yield* TestClock.adjust("1 second");
			const second = yield* Cache.get(cache, "catalog");
			return [first, second] as const;
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toEqual([1, 2]);
	});

	it("evicts the least recently used entry at capacity", async () => {
		const seen: string[] = [];
		const program = Effect.gen(function* () {
			const cache = yield* makeCache((key) =>
				Effect.sync(() => {
					seen.push(key);
					return `${key}-value`;
				}),
			);
			yield* Cache.get(cache, "a");
			yield* Cache.get(cache, "b");
			yield* Cache.get(cache, "a");
			yield* Cache.get(cache, "c");
			yield* Cache.get(cache, "b");
		});

		await Effect.runPromise(program);
		expect(seen).toEqual(["a", "b", "c", "b"]);
	});

	it("refreshes a value and keeps the fresh result cached", async () => {
		let lookups = 0;
		const program = Effect.gen(function* () {
			const cache = yield* makeCache(() =>
				Effect.sync(() => {
					lookups += 1;
					return lookups === 1 ? "stale" : "fresh";
				}),
			);
			yield* Cache.get(cache, "catalog");
			const refreshed = yield* Cache.refresh(cache, "catalog");
			const cached = yield* Cache.get(cache, "catalog");
			return [refreshed, cached] as const;
		});

		await expect(Effect.runPromise(program)).resolves.toEqual([
			"fresh",
			"fresh",
		]);
		expect(lookups).toBe(2);
	});

	it("de-duplicates concurrent in-flight lookups", async () => {
		let lookups = 0;
		let resolveLookup: (() => void) | undefined;
		const program = Effect.gen(function* () {
			const cache = yield* makeCache(() =>
				Effect.callback<string>((resume) => {
					lookups += 1;
					resolveLookup = () => resume(Effect.succeed("shared"));
				}),
			);
			const first = yield* Cache.get(cache, "catalog").pipe(Effect.forkChild);
			yield* Effect.yieldNow;
			const second = yield* Cache.get(cache, "catalog").pipe(Effect.forkChild);
			yield* Effect.yieldNow;
			const lookupCount = lookups;
			resolveLookup?.();
			const values = yield* Effect.all([Fiber.join(first), Fiber.join(second)]);
			return [lookupCount, values] as const;
		});

		await expect(Effect.runPromise(program)).resolves.toEqual([
			1,
			["shared", "shared"],
		]);
	});

	it("does not retain failed lookups when the TTL for failures is zero", async () => {
		let lookups = 0;
		const program = Effect.gen(function* () {
			const cache = yield* makeCache(
				() =>
					Effect.sync(() => {
						lookups += 1;
						return lookups === 1
							? Effect.fail("first failure" as const)
							: Effect.succeed("recovered" as const);
					}).pipe(Effect.flatten),
				{ timeToLive: "1 millis" },
			);
			const first = yield* Effect.exit(Cache.get(cache, "catalog"));
			yield* TestClock.adjust("1 millis");
			const second = yield* Cache.get(cache, "catalog");
			return [first, second] as const;
