import type {
	HevyClient,
	HevyCommitState,
	HevyExecutionOutcome,
	HevyOperationSafety,
	HevyRequestOptions,
	HevyRequestPhase,
} from "@hevy-mcp/hevy-client";
import { isFunction } from "./utils/type-predicates.js";

/** Per-request control supplied by MCP, HTTP, CLI, or a lifecycle owner. */
export interface ToolExecutionContext extends HevyRequestOptions {
	readonly requestId?: string;
}

/** Safe, adapter-neutral execution metadata used in every structured error. */
export interface StructuredExecutionProjection {
	readonly outcome: HevyExecutionOutcome;
	readonly phase: HevyRequestPhase;
	readonly operation_safety: HevyOperationSafety;
	readonly commit_state: HevyCommitState;
	readonly safe_to_retry: boolean;
	readonly code?: string;
	readonly status?: number;
}

/** Backward-compatible name for the structured error projection. */
export type StructuredExecutionError = StructuredExecutionProjection;
type MutableExecutionProjection = {
	-readonly [
		K in keyof StructuredExecutionProjection
	]?: StructuredExecutionProjection[K];
} & Pick<
	StructuredExecutionProjection,
	"outcome" | "phase" | "operation_safety" | "commit_state" | "safe_to_retry"
>;

export type ExecutionProjectionSource = Partial<
	Pick<
		StructuredExecutionProjection,
		| "outcome"
		| "phase"
		| "operation_safety"
		| "commit_state"
		| "safe_to_retry"
		| "code"
		| "status"
	>
>;

export function createExecutionProjection(
	source?: ExecutionProjectionSource,
): StructuredExecutionProjection {
	const projection: MutableExecutionProjection = {
		outcome: source?.outcome ?? "terminal_failure",
		phase: source?.phase ?? "before-dispatch",
		operation_safety: source?.operation_safety ?? "read",
		commit_state: source?.commit_state ?? "not_sent",
		safe_to_retry: source?.safe_to_retry ?? false,
	};
	if (source?.code) projection.code = source.code;
	if (source?.status !== undefined) projection.status = source.status;
	return projection;
}

export function mergeAbortSignals(
	...signals: Array<AbortSignal | undefined>
): AbortSignal | undefined {
	const active = signals.filter(
		(signal): signal is AbortSignal => signal !== undefined,
	);
	if (active.length === 0) return undefined;
	if (active.length === 1) return active[0];
	// Node 24 and the supported Worker runtimes provide AbortSignal.any. The
	// native composition owns listener cleanup when the derived signal settles,
	// avoiding one retained lifecycle/request listener per invocation. Older
	// self-hosted Node runtimes (< 20.3) lack it; the TypeError from the missing
	// static falls through to manual composition instead of failing dispatch.
	try {
		return AbortSignal.any(active);
	} catch (error) {
		if (!(error instanceof TypeError)) throw error;
	}
	const composed = new AbortController();
	const listeners: Array<{
		signal: AbortSignal;
		onAbort: () => void;
	}> = [];
	const abort = (signal: AbortSignal) => {
		for (const listener of listeners) {
			listener.signal.removeEventListener("abort", listener.onAbort);
		}
		listeners.length = 0;
		composed.abort(signal.reason);
	};
	for (const signal of active) {
		if (signal.aborted) {
			abort(signal);
			break;
		}
		const onAbort = () => abort(signal);
		listeners.push({ signal, onAbort });
		signal.addEventListener("abort", onAbort, { once: true });
	}
	return composed.signal;
}

type ClientMethod = keyof HevyClient;

/**
 * The curated client's options slot is deliberately explicit. Inferring it
 * from the final argument is unsafe because IDs and request payloads are also
 * objects/strings and most generated wrappers silently ignore extra args.
 */
/** Canonical options-slot metadata shared by binding and table-driven tests. */
export const HEVY_CLIENT_OPTION_INDEXES = {
	getWorkouts: 1,
	getWorkout: 1,
	createWorkout: 1,
	updateWorkout: 2,
	getWorkoutCount: 0,
	getWorkoutEvents: 1,
	getRoutines: 1,
	getRoutineById: 1,
	createRoutine: 1,
	updateRoutine: 2,
	getExerciseTemplates: 1,
	getExerciseTemplate: 1,
	getExerciseHistory: 2,
	createExerciseTemplate: 1,
	getRoutineFolders: 1,
	createRoutineFolder: 1,
	getRoutineFolder: 1,
	getBodyMeasurements: 1,
	getBodyMeasurement: 1,
	createBodyMeasurement: 1,
	updateBodyMeasurement: 2,
	getUserInfo: 0,
} satisfies Record<ClientMethod, number>;

/**
 * Bind one immutable control object to every curated client operation. A
 * proxy keeps existing tool code source-compatible while making it impossible
 * for one page of a workflow to silently lose cancellation/deadline state.
 */
export function bindClientExecution<TClient extends HevyClient>(
	client: TClient,
	control: ToolExecutionContext,
): TClient {
	return new Proxy(client, {
		get(target, property, receiver) {
			const value = Reflect.get(target, property, receiver);
			if (!isFunction(value)) return value;
			const optionIndex =
				property in HEVY_CLIENT_OPTION_INDEXES
					? HEVY_CLIENT_OPTION_INDEXES[property as ClientMethod]
					: undefined;
			if (optionIndex === undefined) {
				return value.bind(target);
			}
			return (...args: unknown[]) => {
				const provided = args[optionIndex] as HevyRequestOptions | undefined;
				const merged: HevyRequestOptions = {
					...provided,
					...control,
				};
				args[optionIndex] = merged;
				return Reflect.apply(value, target, args);
			};
		},
	}) as TClient;
}

import type { McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { Effect } from "effect";
import { z } from "zod";
import { respond, type ResponseContract } from "../utils/response-contracts.js";
import { compactJsonSchema } from "../utils/compact-json-schema.js";
import type { InferToolParams } from "../utils/tool-helpers.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import type { ToolRuntime } from "./tool-runtime.js";
import type { ToolExecutionContext } from "../execution.js";

type ToolDefinitionBase<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: TSchema;
	readonly annotations: ToolAnnotations;
	readonly responseContract: ResponseContract<TResult>;
	execute(
		runtime: ToolRuntime,
		args: InferToolParams<TSchema>,
	): Effect.Effect<TResult, unknown, never>;
};

type RegisteredToolConfig = {
	description: string;
	inputSchema: ReturnType<typeof compactJsonSchema>;
	annotations: ToolAnnotations;
	outputSchema?: ReturnType<typeof compactJsonSchema>;
};

export type ToolRegistrar = Pick<McpServer, "registerTool">;

export type ToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = ToolDefinitionBase<TSchema, TResult> &
	(
		| {
				readonly kind: "read";
				readonly outputSchema: z.ZodRawShape;
		  }
		| {
				readonly kind: "write";
				readonly outputSchema?: z.ZodRawShape;
		  }
	);

type AnyToolDefinition = ToolDefinition<Record<string, z.ZodTypeAny>, unknown>;

/**
 * One-time-per-isolate registration metadata for each tool definition.
 *
 * Building a tool's compact JSON Schema (and the SDK's eager wire conversion
 * of the `compactJsonSchema`-wrapped schema on registration) is the dominant
 * CPU cost when constructing an MCP server. Tool definitions are module-level
 * constants, so this metadata can be computed once and shared by every server
 * a single isolate builds. The SDK's `registerTool` reads the schema strictly
 * through the Standard Schema interface and never mutates it, so sharing the
 * memoized config across concurrent servers is safe.
 *
 * Keep the memo lazy: CLI and test processes that never build a Hevy server
 * pay nothing. Isolate-based edge runtimes that want the one-time conversion
 * moved into module-scope (outside request CPU) call `preloadHevyToolSchemas`.
 */
const registeredToolConfigCache = new WeakMap<
	AnyToolDefinition,
	RegisteredToolConfig
>();

export function getRegisteredToolConfig(
	definition: AnyToolDefinition,
): RegisteredToolConfig {
	const cached = registeredToolConfigCache.get(definition);
	if (cached) return cached;
	const config: RegisteredToolConfig = {
		description: definition.description,
		inputSchema: compactJsonSchema(z.strictObject(definition.inputSchema)),
		annotations: definition.annotations,
	};
	if (definition.outputSchema) {
		config.outputSchema = compactJsonSchema(z.object(definition.outputSchema));
	}
	registeredToolConfigCache.set(definition, config);
	return config;
}

export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: AnyToolDefinition,
): void {
	const directHandler = (
		args: InferToolParams<typeof definition.inputSchema>,
		requestContext?: ToolExecutionContext,
	) =>
		Effect.suspend(() => {
			const scopedRuntime = requestContext
				? runtime.forExecution(requestContext)
				: runtime;
			return definition
				.execute(scopedRuntime, args)
				.pipe(Effect.map((data) => respond(definition.responseContract, data)));
		});
	const handler = runtime.createHandler(directHandler, definition.name, {
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
	});

	const config = getRegisteredToolConfig(definition);
	server.registerTool(definition.name, config, (args, context) =>
		handler(
			z.strictObject(definition.inputSchema).parse(args),
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		),
	);
}

